import java.util.Scanner;

public class sd2 {
    static boolean check(int[] arr, int i, int end, int w) {
        if (i > end) {
            return true;
        }
        int d = arr[i];
        if (d != 0 && d != 1 && d != w && d != w - 1) {
            return false;
        }
        if (d == w || d == w - 1) {
            arr[i + 1]++;
        }
        return check(arr, i + 1, end, w);
    }

    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        int w = s.nextInt();
        int m = s.nextInt();
        int[] arr = new int[40];
        int cntr = 0;

        while (m > 0) {
            arr[cntr++] = m % w;
            m /= w;
        }

        System.out.println(check(arr, 0, cntr, w) ? "YES" : "NO");
    }
}
